/**
 * Thin Bee client — Phase 1 reaches exactly one confirmed endpoint: GET /v1/me
 * (Bee docs, "API": `GET /v1/me` returns the user profile; confirmed 2026-06-07).
 *
 * CUSTODY (v0.3 amendment, ledger E0012): the Bee bearer is NO LONGER a Worker
 * secret. It is passed in explicitly — the caller reads it from the request's
 * decrypted per-grant props (GrantProps.beeToken) or, at consent time, from the
 * value the operator just pasted (to validate it before binding). This module
 * never touches `env.BEE_API_TOKEN` (there is none).
 *
 * NETWORK PATH (private-CA bridge, resolved E0012; bound container, D0028): the
 * caller passes the bound Container stub (`getContainer(env.BEE_BRIDGE)`) and we
 * call it over an INTERNAL Worker->container fetch. Inside, caddy re-originates
 * TLS to Bee trusting bee-ca.pem, so the old "Worker can't trust Bee's private
 * CA" seam is handled by the container, not here. A transport failure now means
 * the bridge container is unreachable or misconfigured (or the BEE_BRIDGE binding
 * is missing), not a Worker TLS-trust problem.
 *
 * HONEST + SAFEST (binding): the Bee bearer is attached only to the outbound
 * request. It is NEVER logged and NEVER serialized into a returned error. Errors
 * carry status + a generic message only — never the request, headers, token, or
 * raw upstream body.
 */

export interface BeeWhoami {
  ok: true;
  account: unknown; // shape unconfirmed against the live API — passed through minimally
  /** Whether the bridge container served this request cold (telemetry only). */
  bridgeCold?: boolean;
  /** bridge.fetch round-trip wall-clock in ms — the cold/warm leg only (telemetry only). */
  bridgeMs?: number;
}

export interface BeeError {
  ok: false;
  status: number | null;
  message: string;
  /** Whether the bridge container served this request cold (telemetry only).
   *  Present whenever the bridge responded — including non-2xx, which still
   *  carries x-bridge-cold; absent only when no round-trip happened. */
  bridgeCold?: boolean;
  /** bridge.fetch round-trip wall-clock in ms — the cold/warm leg only (telemetry only). */
  bridgeMs?: number;
}

/** Call GET /v1/me through the bound bridge container with an explicit bearer.
 *  The single Bee primitive. `bridge` is the stub from getContainer(env.BEE_BRIDGE). */
export async function beeGetMe(beeToken: string, bridge: DurableObjectStub): Promise<BeeWhoami | BeeError> {
  if (!beeToken || !bridge) {
    return {
      ok: false,
      status: null,
      message:
        "Bee not configured: the BEE_BRIDGE container binding must be present and the grant must carry a Bee token (reconnect to supply one).",
    };
  }

  let res: Response;
  const t0 = Date.now();
  try {
    // Internal Worker->container call. The host in this URL is arbitrary (the
    // bound container is addressed by the stub, not by DNS); caddy's :8080 port
    // site accepts any Host and forwards only /v1/* to Bee.
    res = await bridge.fetch("http://bee-bridge/v1/me", {
      headers: {
        authorization: `Bearer ${beeToken}`,
        accept: "application/json",
        "user-agent": "bee-ai-auth-mcp",
      },
    });
  } catch {
    // Bridge container unreachable / not deployed. Do NOT echo the request or any
    // secret — a generic, actionable message only.
    return {
      ok: false,
      status: null,
      message:
        "Could not reach the Bee API through the bridge. Confirm the private-CA Container bridge is deployed and the BEE_BRIDGE binding is wired (see bridge/README.md).",
      bridgeMs: Date.now() - t0,
    };
  }
  // bridge_ms is the bridge.fetch round-trip ONLY (the cold/warm-sensitive leg,
  // docs/telemetry-governance.md) — captured here, before res.json() reads the
  // body, so payload transfer never inflates the cold/warm signal. x-bridge-cold
  // rides every proxied response (success or not), so read it for both branches.
  const bridgeMs = Date.now() - t0;
  const bridgeCold = res.headers.get("x-bridge-cold") === "1";

  if (!res.ok) {
    // Never serialize the upstream body or our request — status + generic text only.
    return {
      ok: false,
      status: res.status,
      message:
        res.status === 401 || res.status === 403
          ? "Bee rejected the credential (401/403). Reconnect and paste a current Bee token, or rotate it in the Bee app."
          : `Bee returned an unexpected status (${res.status}).`,
      bridgeCold,
      bridgeMs,
    };
  }

  const account = (await res.json().catch(() => null)) as unknown;
  return { ok: true, account, bridgeCold, bridgeMs };
}

/** Bee's search endpoints are POST + JSON body but are READ operations (no
 *  mutation). They are the only non-GET paths bee_read is permitted to call. */
const BEE_SEARCH_PATHS = new Set<string>([
  "/v1/search/conversations",
  "/v1/search/conversations/neural",
]);

export interface BeeReadResult {
  ok: true;
  status: number;
  body: unknown;
  truncated?: boolean;
  /** Whether the bridge container served this request cold (telemetry only). */
  bridgeCold?: boolean;
  /** bridge.fetch round-trip wall-clock in ms — the cold/warm leg only (telemetry only). */
  bridgeMs?: number;
}

/** Generalized read passthrough — the Phase-2 `bee_read` primitive. Read-only BY
 *  CONSTRUCTION: it issues GET to any /v1/* path, OR POST to an allow-listed
 *  /v1/search/* path (non-mutating search). It never issues a mutating verb, so
 *  the read-only guarantee is structural, not advisory. /v1/stream (SSE) is
 *  refused (long-lived, not request/response). Same custody, bridge, and
 *  no-secret-in-errors rules as beeGetMe. */
export async function beeRead(
  beeToken: string,
  bridge: DurableObjectStub,
  rawPath: string,
  searchBody?: unknown
): Promise<BeeReadResult | BeeError> {
  if (!beeToken || !bridge) {
    return {
      ok: false,
      status: null,
      message:
        "Bee not configured: the BEE_BRIDGE container binding must be present and the grant must carry a Bee token (reconnect to supply one).",
    };
  }
  const path = (rawPath || "").trim();
  if (!path.startsWith("/v1/") || path.includes("..")) {
    return { ok: false, status: null, message: "Path must be a Bee API path beginning with /v1/ (no traversal)." };
  }
  const pathname = path.split("?")[0];
  if (pathname === "/v1/stream") {
    return { ok: false, status: null, message: "/v1/stream is a Server-Sent Events stream and is not available through bee_read." };
  }
  const isSearch = BEE_SEARCH_PATHS.has(pathname);
  const method = isSearch ? "POST" : "GET";

  const headers: Record<string, string> = {
    authorization: `Bearer ${beeToken}`,
    accept: "application/json",
    "user-agent": "bee-ai-auth-mcp",
  };
  const init: RequestInit = { method, headers };
  if (isSearch) {
    headers["content-type"] = "application/json";
    init.body = JSON.stringify(searchBody ?? {});
  }

  let res: Response;
  const t0 = Date.now();
  try {
    res = await bridge.fetch(`http://bee-bridge${path}`, init);
  } catch {
    return {
      ok: false,
      status: null,
      message:
        "Could not reach the Bee API through the bridge. Confirm the private-CA Container bridge is deployed and the BEE_BRIDGE binding is wired (see bridge/README.md).",
      bridgeMs: Date.now() - t0,
    };
  }
  // bridge_ms is the bridge.fetch round-trip ONLY (the cold/warm-sensitive leg,
  // docs/telemetry-governance.md) — captured here, before res.text() downloads
  // up to the 512KB body, so payload size never inflates the cold/warm signal.
  // x-bridge-cold rides every proxied response (success or not), so read it for
  // all branches below.
  const bridgeMs = Date.now() - t0;
  const bridgeCold = res.headers.get("x-bridge-cold") === "1";

  if (!res.ok) {
    return {
      ok: false,
      status: res.status,
      message:
        res.status === 401 || res.status === 403
          ? "Bee rejected the credential (401/403). Reconnect and paste a current Bee token, or rotate it in the Bee app."
          : `Bee returned an unexpected status (${res.status}).`,
      bridgeCold,
      bridgeMs,
    };
  }

  const text = await res.text().catch(() => "");
  const CAP = 512 * 1024; // guard so a huge list can't blow the client's context
  if (text.length > CAP) {
    return {
      ok: true,
      status: res.status,
      truncated: true,
      bridgeCold,
      bridgeMs,
      body: {
        note: "Response exceeded the 512KB read cap and was truncated. Use pagination (limit/cursor) or a narrower path/query.",
        preview: text.slice(0, CAP),
      },
    };
  }
  let body: unknown;
  try {
    body = JSON.parse(text);
  } catch {
    body = text;
  }
  return { ok: true, status: res.status, body, bridgeCold, bridgeMs };
}

src/bridge.ts.content:
/**
 * BeeBridge — the private-CA bridge as a bound Cloudflare Container (D0028, ledger
 * E0014). The relay Worker reaches it over an INTERNAL Worker->container call
 * (`getContainer(env.BEE_BRIDGE).fetch(...)`), never a public hostname. Inside the
 * container, caddy (see bridge/Dockerfile + bridge/Caddyfile) listens on
 * `defaultPort` and re-originates TLS to Bee trusting bee-ca.pem — the one thing a
 * stock Worker `fetch` cannot do because Bee's direct API uses a private CA
 * (ledger E0012).
 *
 * Data-plane job: pass BEE_UPSTREAM/BEE_SNI into caddy. Token-AGNOSTIC shared
 * infrastructure (E0014): every /v1 request carries its own user's bearer in
 * Authorization — never injected here, never stored, never logged. One shared
 * instance (`getContainer` default); do NOT add per-user instance names.
 *
 * Auth-broker job (kitchen CLI-BROKER-AMENDMENT-2026-09-08): RPC methods run
 * Bee CLI via Container exec under an opaque per-attempt BEE_CONFIG_DIR, then
 * delete that directory. This is a one-shot handshake, not a shared Bee login.
 *
 * The runtime must SEE this class for the `migrations` entry (wrangler.jsonc
 * `new_sqlite_classes: ["BeeBridge"]`) to register the Durable Object, so it is
 * re-exported from src/index.ts.
 */

import { Container } from "@cloudflare/containers";
import {
  assertBrokerId,
  brokerConfigDir,
  brokerExecArgv,
  decodeBrokerExec,
  finishBrokerExec,
  parseBrokerClear,
  parseBrokerResume,
  parseBrokerStart,
  type BrokerClearResult,
  type BrokerCommand,
  type BrokerResumeResult,
  type BrokerStartResult,
} from "./broker";
import type { Env } from "./types";

/** Only host + SNI are passed into the container process environment. */
export function bridgeContainerEnv(env: Pick<Env, "BEE_UPSTREAM" | "BEE_SNI">): {
  BEE_UPSTREAM: string;
  BEE_SNI: string;
} {
  return { BEE_UPSTREAM: env.BEE_UPSTREAM, BEE_SNI: env.BEE_SNI };
}

type ContainerExec = {
  running: boolean;
  exec(
    cmd: string[],
    options?: { env?: Record<string, string> }
  ): Promise<{ output(): Promise<{ stdout: ArrayBuffer; stderr: ArrayBuffer; exitCode: number }> }>;
};

export class BeeBridge extends Container<Env> {
  /** caddy's internal listener (bridge/Caddyfile `:8080` site). The Worker's
   *  container fetch is forwarded here by the Containers runtime. */
  defaultPort = 8080;
  /** Idle the instance after inactivity; it cold-starts on the next request.
   *  whoami is bursty, not steady, so there is no value in holding it warm. */
  sleepAfter = "10m";

  /** A Cloudflare container does NOT inherit the Worker's vars/secrets, so caddy's
   *  {$BEE_UPSTREAM}/{$BEE_SNI} (bridge/Caddyfile) would start empty and the
   *  reverse_proxy to Bee would fail. Pass the operator-set secrets through as the
   *  container's environment. Token-AGNOSTIC still holds: no per-user bearer is set
   *  here — that rides the Authorization header per request, straight to Bee. */
  envVars = bridgeContainerEnv(this.env);

  /** Cold-start signal (telemetry only — shape, not application logic). `onStart`
   *  fires when the container starts; the first request after a start is served
   *  "cold". We surface that to the Worker as an `x-bridge-cold` response header
   *  so telemetry can split the bimodal cold/warm latency (the whole point of the
   *  baseline). Read+cleared per request; the DO instance loses it on eviction,
   *  which is exactly a cold start. See docs/telemetry-governance.md. */
  private coldPending = false;

  override onStart(): void {
    this.coldPending = true;
  }

  override async fetch(request: Request): Promise<Response> {
    try {
      const res = await super.fetch(request);
      // onStart fires inside super.fetch on a cold start, so read the flag after.
      const cold = this.coldPending;
      const headers = new Headers(res.headers);
      headers.set("x-bridge-cold", cold ? "1" : "0");
      return new Response(res.body, { status: res.status, statusText: res.statusText, headers });
    } finally {
      // Clear even when super.fetch throws, so a failed cold request can't leave
      // the flag set and mark later warm requests as cold in telemetry.
      this.coldPending = false;
    }
  }

  /** One-shot CLI start: print connect URL only. Never a shared login. */
  async startBeeBroker(brokerId: string): Promise<BrokerStartResult> {
    if (!assertBrokerId(brokerId)) return { status: "error", message: "invalid broker id" };
    try {
      return finishBrokerExec(await this.execBroker(brokerId, "start"), parseBrokerStart);
    } catch {
      return { status: "error", message: "hosted Bee CLI broker unreachable" };
    }
  }

  /** Bounded resume under the same opaque directory. Token is returned only
   *  to the Worker invocation that asked — never logged. */
  async resumeBeeBroker(brokerId: string): Promise<BrokerResumeResult> {
    if (!assertBrokerId(brokerId)) return { status: "error", message: "invalid broker id" };
    try {
      return finishBrokerExec(await this.execBroker(brokerId, "resume"), parseBrokerResume);
    } catch {
      return { status: "error", message: "hosted Bee CLI broker unreachable" };
    }
  }

  async clearBeeBroker(brokerId: string): Promise<BrokerClearResult> {
    if (!assertBrokerId(brokerId)) return { status: "error", message: "invalid broker id" };
    try {
      return finishBrokerExec(await this.execBroker(brokerId, "clear"), parseBrokerClear);
    } catch {
      return { status: "error", message: "hosted Bee CLI broker unreachable" };
    }
  }

  private containerExec(): ContainerExec | null {
    const container = (this.ctx as DurableObjectState & { container?: ContainerExec }).container;
    return container ?? null;
  }

  private async execBroker(
    brokerId: string,
    command: BrokerCommand
  ): Promise<{ stdout: string; exitCode: number }> {
    const dir = brokerConfigDir(brokerId);
    const argv = brokerExecArgv(command, brokerId);
    if (!dir || !argv) throw new Error("invalid broker id");
    const container = this.containerExec();
    if (!container) throw new Error("container exec unavailable");
    if (!container.running) {
      await this.startAndWaitForPorts(this.defaultPort);
    }
    const process = await container.exec(argv, {
      env: {
        BEE_CONFIG_DIR: dir,
        BEE_FORCE_FILE_STORE: "1",
        HOME: "/tmp",
        PATH: "/usr/local/bin:/usr/bin",
      },
    });
    const output = await process.output();
    // Decode stdout for the parser only. Do not log stdout or stderr —
    // resume completed is the one-shot token handoff. Nonzero exit is
    // never treated as success by finishBrokerExec.
    return decodeBrokerExec(output);
  }
}

src/broker.ts.content:
/**
 * Hosted Bee CLI auth broker — one-shot pairing, never a shared Bee session.
 *
 * Kitchen: rail/3-pass/2026-08-13-bee-relay-cf-access/CLI-BROKER-AMENDMENT-2026-09-08.md
 *
 * The bound container's long-lived process remains caddy (token-agnostic data
 * plane). Bee CLI runs only via Container exec under an opaque per-attempt
 * BEE_CONFIG_DIR. The resulting bearer is moved into encrypted grant props and
 * the broker directory is deleted. Never derive a path from email/login.
 * Never log a token, CLI stdout wholesale, or broker directory contents.
 */

// ---- opaque broker id (never email / login / clientId) ----
export const BROKER_ID_RE = /^[a-f0-9]{32}$/;
export const BROKER_ROOT = "/tmp/bee-broker";

export function newBrokerId(random: Uint8Array = crypto.getRandomValues(new Uint8Array(16))): string {
  return Array.from(random, (b) => b.toString(16).padStart(2, "0")).join("");
}

export function assertBrokerId(id: string): string | null {
  return BROKER_ID_RE.test(id) ? id : null;
}

/** Absolute config dir for one pairing attempt. Null on any id that is not opaque hex. */
export function brokerConfigDir(id: string): string | null {
  const ok = assertBrokerId(id);
  return ok ? `${BROKER_ROOT}/${ok}` : null;
}

/**
 * Best-effort delete target. Returns the exact directory to remove, or null if
 * the id is invalid. Callers must refuse to delete anything else — including
 * BROKER_ROOT itself or a sibling.
 */
export function brokerClearTarget(id: string): string | null {
  return brokerConfigDir(id);
}

export function brokerClearWouldTouch(otherId: string, targetId: string): boolean {
  const a = brokerClearTarget(otherId);
  const b = brokerClearTarget(targetId);
  return Boolean(a && b && a === b);
}

// ---- CLI connect-URL extraction (the only pairing material allowed out) ----
const CONNECT_URL_RE = /https:\/\/bee\.computer\/connect#[A-Za-z0-9_-]+/;

export function extractConnectUrl(text: string): string | null {
  const m = text.match(CONNECT_URL_RE);
  return m ? m[0] : null;
}

// ---- broker helper wire (one JSON line on stdout) ----
export type BrokerStartResult =
  | { status: "pending"; connectUrl: string; expiresAt?: string }
  | { status: "error"; message: string };

export type BrokerResumeResult =
  | { status: "pending" }
  | { status: "expired" }
  | { status: "completed"; token: string }
  | { status: "error"; message: string };

export type BrokerClearResult = { status: "cleared" } | { status: "error"; message: string };

const SENSITIVE_KEY_RE = /token|secret|key|authorization|bearer/i;

/** Redact token/secret fields for any diagnostic. Never log the raw helper line. */
export function sanitizeBrokerLine(line: string): string {
  const trimmed = line.trim();
  if (!trimmed) return "<empty>";
  try {
    const parsed = JSON.parse(trimmed) as unknown;
    if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
      return "<non-object>";
    }
    const parts: string[] = [];
    for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
      if (SENSITIVE_KEY_RE.test(k)) {
        const n = typeof v === "string" ? v.length : JSON.stringify(v)?.length ?? 0;
        parts.push(`${k}=<redacted:${n}>`);
      } else if (typeof v === "string") {
        parts.push(`${k}=${v.length > 80 ? `${v.slice(0, 79)}…` : v}`);
      } else {
        parts.push(`${k}=${typeof v}`);
      }
    }
    return `{${parts.join(", ")}}`;
  } catch {
    // Refuse to echo unstructured CLI text — it can contain a token or QR.
    return `<non-json:${trimmed.length}>`;
  }
}

export function parseBrokerStart(stdout: string): BrokerStartResult {
  const parsed = parseFirstJsonObject(stdout);
  if (!parsed) return { status: "error", message: "hosted Bee CLI broker returned no result" };
  if (parsed.status === "pending" && typeof parsed.connectUrl === "string") {
    if (!extractConnectUrl(parsed.connectUrl)) {
      return { status: "error", message: "hosted Bee CLI broker returned an invalid connect URL" };
    }
    const expiresAt = typeof parsed.expiresAt === "string" ? parsed.expiresAt : undefined;
    return expiresAt
      ? { status: "pending", connectUrl: parsed.connectUrl, expiresAt }
      : { status: "pending", connectUrl: parsed.connectUrl };
  }
  if (parsed.status === "error") {
    return { status: "error", message: brokerErrorMessage(parsed.message) };
  }
  return { status: "error", message: "hosted Bee CLI broker returned an unexpected start shape" };
}

export function parseBrokerResume(stdout: string): BrokerResumeResult {
  const parsed = parseFirstJsonObject(stdout);
  if (!parsed) return { status: "error", message: "hosted Bee CLI broker returned no result" };
  if (parsed.status === "pending") return { status: "pending" };
  if (parsed.status === "expired") return { status: "expired" };
  if (parsed.status === "completed" && typeof parsed.token === "string" && parsed.token.length > 0) {
    return { status: "completed", token: parsed.token };
  }
  if (parsed.status === "error") {
    return { status: "error", message: brokerErrorMessage(parsed.message) };
  }
  return { status: "error", message: "hosted Bee CLI broker returned an unexpected resume shape" };
}

export function parseBrokerClear(stdout: string): BrokerClearResult {
  const parsed = parseFirstJsonObject(stdout);
  if (!parsed) return { status: "error", message: "hosted Bee CLI broker returned no result" };
  if (parsed.status === "cleared") return { status: "cleared" };
  if (parsed.status === "error") {
    return { status: "error", message: brokerErrorMessage(parsed.message) };
  }
  return { status: "error", message: "hosted Bee CLI broker returned an unexpected clear shape" };
}

/** Decode exec output for parsers only. Never log stdout or stderr. */
export function decodeBrokerExec(output: {
  stdout: ArrayBuffer | Uint8Array | string;
  stderr?: ArrayBuffer | Uint8Array | string;
  exitCode: number;
}): { stdout: string; exitCode: number } {
  void output.stderr;
  const stdout =
    typeof output.stdout === "string" ? output.stdout : new TextDecoder().decode(output.stdout);
  return { stdout, exitCode: output.exitCode };
}

/** Nonzero helper exits are never success, even if stdout looks like pending/cleared/completed. */
export function finishBrokerExec<T extends { status: string }>(
  decoded: { stdout: string; exitCode: number },
  parse: (stdout: string) => T
): T | { status: "error"; message: string } {
  const parsed = parse(decoded.stdout);
  if (decoded.exitCode !== 0 && parsed.status !== "error") {
    return { status: "error", message: "hosted Bee CLI broker failed" };
  }
  return parsed;
}

function brokerErrorMessage(message: unknown): string {
  return typeof message === "string" && message.length > 0 && message.length < 200
    ? message
    : "hosted Bee CLI broker failed";
}

function parseFirstJsonObject(stdout: string): Record<string, unknown> | null {
  for (const line of stdout.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(trimmed) as unknown;
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed as Record<string, unknown>;
      }
    } catch {
      continue;
    }
  }
  return null;
}

// ---- sealed broker state (consent page carries ciphertext only) ----
export interface SealedBrokerState {
  kind: "cli-broker-v1";
  brokerId: string;
  login: string;
  clientId: string;
  iat: number;
}

const SEALED_MAX_AGE_MS = 15 * 60 * 1000;

function te(s: string): Uint8Array {
  return new TextEncoder().encode(s);
}

function b64urlFromBytes(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlToBytes(s: string): Uint8Array {
  const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (s.length % 4)) % 4));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function sealKey(secret: string): Promise<CryptoKey> {
  const ikm = await crypto.subtle.importKey("raw", te(secret), "HKDF", false, ["deriveKey"]);
  return crypto.subtle.deriveKey(
    { name: "HKDF", hash: "SHA-256", salt: te("bee-broker-v1"), info: te("sealed-state") },
    ikm,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

export async function sealBrokerState(state: SealedBrokerState, secret: string): Promise<string> {
  const key = await sealKey(secret);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(
    await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, te(JSON.stringify(state)))
  );
  const packed = new Uint8Array(iv.length + ct.length);
  packed.set(iv, 0);
  packed.set(ct, iv.length);
  return b64urlFromBytes(packed);
}

export async function unsealBrokerState(
  blob: string,
  secret: string,
  now: number = Date.now()
): Promise<SealedBrokerState | null> {
  let packed: Uint8Array;
  try {
    packed = b64urlToBytes(blob);
  } catch {
    return null;
  }
  if (packed.length <= 12) return null;
  const iv = packed.subarray(0, 12);
  const ct = packed.subarray(12);
  let plain: Uint8Array;
  try {
    const key = await sealKey(secret);
    plain = new Uint8Array(await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ct));
  } catch {
    return null;
  }
  let state: SealedBrokerState;
  try {
    state = JSON.parse(new TextDecoder().decode(plain)) as SealedBrokerState;
  } catch {
    return null;
  }
  if (
    state?.kind !== "cli-broker-v1" ||
    !assertBrokerId(state.brokerId) ||
    typeof state.login !== "string" ||
    typeof state.clientId !== "string" ||
    typeof state.iat !== "number"
  ) {
    return null;
  }
  if (now - state.iat > SEALED_MAX_AGE_MS) return null;
  return state;
}

/** Id to clear for this consent identity only. Null if the blob is missing,
 *  stale, or belongs to another login/client — never a sibling directory. */
export function ownedBrokerId(
  state: SealedBrokerState | null,
  login: string,
  clientId: string
): string | null {
  if (!state) return null;
  if (state.login !== login || state.clientId !== clientId) return null;
  return assertBrokerId(state.brokerId);
}

/** Compiled helper — no bun/shell in the final image. */
export const BROKER_HELPER_ARGV = ["/opt/bee-broker/broker"] as const;

export const BROKER_COMMANDS = ["start", "resume", "clear"] as const;
export type BrokerCommand = (typeof BROKER_COMMANDS)[number];

/** The only argv BeeBridge may exec. Never `bee proxy` — that injects one
 *  CLI login's bearer into every /v1 request (bee-cli proxy/index.ts). */
export function brokerExecArgv(command: string, brokerId: string): string[] | null {
  if (!BROKER_COMMANDS.includes(command as BrokerCommand)) return null;
  if (!assertBrokerId(brokerId)) return null;
  return [...BROKER_HELPER_ARGV, command, brokerId];
}

export interface BeeBroker {
  startBeeBroker(brokerId: string): Promise<BrokerStartResult>;
  resumeBeeBroker(brokerId: string): Promise<BrokerResumeResult>;
  clearBeeBroker(brokerId: string): Promise<BrokerClearResult>;
}

