/**
 * Origin-header validation — Connectors Directory technical requirement.
 * Ported verbatim from git-repo-auth-mcp (6B borrow, 2026-06-10): no substrate
 * covers Origin validation for a Workers MCP deployment, so this ~20-line check
 * is hand-rolled deliberately.
 *
 * Rule: requests without an Origin header pass (server-to-server clients send
 * none; OAuth navigations send none). Requests WITH an Origin must match the
 * deployment's own host or an entry in ALLOWED_ORIGINS (comma-separated,
 * per-deployment — policy in config, not code).
 */
export function isOriginAllowed(
  originHeader: string | null,
  requestUrl: string,
  allowedOrigins?: string
): boolean {
  if (!originHeader) return true; // non-browser clients and navigations
  let origin: URL;
  try {
    origin = new URL(originHeader);
  } catch {
    return false; // malformed Origin is hostile until proven otherwise
  }
  const self = new URL(requestUrl);
  if (origin.host === self.host && origin.protocol === self.protocol) return true;
  if (!allowedOrigins) return false;
  return allowedOrigins
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .some((allowed) => {
      try {
        const a = new URL(allowed);
        return a.host === origin.host && a.protocol === origin.protocol;
      } catch {
        return false;
      }
    });
}

src/pairing.ts.content:
/**
 * Legacy Worker-side Bee QR pairing protocol helpers.
 *
 * Consent `/pairing/*` now uses the hosted Bee CLI broker (`src/broker.ts`).
 * This module remains for protocol facts and unit coverage of the CLI wire
 * format. Do not add a new Bee app_id here.
 *
 * Replicates the @beeai/cli pairing handshake from inside the Worker so the
 * consent screen can offer a QR instead of token-hunting. Protocol facts were
 * re-verified against the @beeai/cli@0.7.3 binary and a live probe on
 * 2026-07-05 (odd/ledger/2026-07-05-consent-qr-pairing-execution.md):
 *
 *   POST https://auth.beeai-services.com/apps/pairing/request
 *        { app_id, publicKey (base64 x25519) }
 *     -> { ok, status: "pending",   requestId, expiresAt }       (fresh key)
 *     -> { ok, status: "pending",   requestId, expiresAt }       (re-POST = poll)
 *     -> { ok, status: "completed", encryptedToken [, requestId] } (after approval)
 *     -> { ok, status: "expired",   requestId }                  (~5-min window)
 *
 *   The poll IS the same POST — the service is idempotent on publicKey, so a
 *   stateless Worker can poll without remembering anything server-side.
 *
 *   encryptedToken = base64( version(1)=0x01 || nonce(24) || senderPk(32) || box )
 *   i.e. crypto_box (x25519-xsalsa20-poly1305) sealed to OUR ephemeral key.
 *
 * Custody: the Worker keeps NO pairing state. The ephemeral keypair rides in a
 * sealed blob — AES-256-GCM under an HKDF-SHA256 key derived from
 * CONSENT_SIGNING_SECRET (the consent-HMAC anchor; no additional secret to
 * steward) — held by the consent page and posted back on each poll. The
 * secret key is plaintext only inside a single request invocation; the Bee
 * token, once decrypted, follows the exact paste-path route (bridge-validated
 * via beeGetMe, then straight into encrypted grant props). Nothing secret is
 * ever logged; requestIds and public keys are the only pairing material that
 * may surface in logs or UI (charter §5).
 */

import nacl from "tweetnacl";

// ---- protocol constants (verbatim from @beeai/cli@0.7.3) ----
export const PAIRING_URL = "https://auth.beeai-services.com/apps/pairing/request";
/** The Bee CLI's registered prod app id. Reusing it means the Bee approval
 *  screen presents as the CLI — accepted for personal self-host (charter §3,
 *  ledger D0035); a relay-registered app id is the multi-tenant gate. Do not
 *  mint, register, or spoof any other app identity without an operator ruling. */
export const BEE_CLI_APP_ID = "ph9fssu1kv1b0hns69fxf7rx";
const ENCRYPTION_VERSION = 1;
const NONCE_SIZE = 24;
const PUBLIC_KEY_SIZE = 32;
const MIN_ENVELOPE_SIZE = 1 + NONCE_SIZE + PUBLIC_KEY_SIZE + 16;
/** Belt-and-braces ceiling on sealed-state age; the service itself expires
 *  pairings at ~5 minutes. */
const SEALED_MAX_AGE_MS = 15 * 60 * 1000;

// ---- byte/base64 helpers (standard base64 — the pairing wire format) ----
function te(s: string): Uint8Array {
  return new TextEncoder().encode(s);
}

export function bytesToB64(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

export function b64ToBytes(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function b64urlFromBytes(bytes: Uint8Array): string {
  return bytesToB64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlToBytes(s: string): Uint8Array {
  return b64ToBytes(s.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (s.length % 4)) % 4));
}

// ---- ephemeral keypair ----
export interface PairingKeyPair {
  /** standard base64, exactly as sent in the pairing request body */
  publicKeyB64: string;
  secretKey: Uint8Array;
}

export function generatePairingKeyPair(): PairingKeyPair {
  const kp = nacl.box.keyPair();
  return { publicKeyB64: bytesToB64(kp.publicKey), secretKey: kp.secretKey };
}

// ---- the pairing request/poll (one POST; idempotent on publicKey) ----
export type PairingOutcome =
  | { status: "pending"; requestId: string; expiresAt: string }
  | { status: "completed"; requestId: string; encryptedToken: string }
  | { status: "expired" }
  | { status: "error"; message: string };

// ---- sanitized shape diagnostics ----
// When the service answers 200 with a body we don't recognize, we want the
// *shape* in the error/log so the next failure is self-diagnosing — without
// ever letting token/secret material through. Keys matching /token|secret|key/i
// are redacted to "<redacted:N>" (N = value length); everything else is
// JSON-rendered and truncated. requestIds and public keys are the only
// pairing material allowed in output (charter §5) — and /key/i redacts the
// public key anyway, erring on the safe side.
const SENSITIVE_KEY_RE = /token|secret|key/i;
const DIAG_VALUE_MAX = 40;
const DIAG_MESSAGE_MAX = 240;

function truncateStr(s: string, max: number): string {
  return s.length <= max ? s : s.slice(0, max - 1) + "…";
}

function renderValue(v: unknown): string {
  try {
    return JSON.stringify(v) ?? String(v);
  } catch {
    return "<unrenderable>";
  }
}

/** Shallow-map a response body into a redaction-safe, truncated description. */
export function sanitizePairingBody(body: unknown): string {
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return truncateStr(renderValue(body), DIAG_VALUE_MAX);
  }
  const parts: string[] = [];
  for (const [k, v] of Object.entries(body as Record<string, unknown>)) {
    if (SENSITIVE_KEY_RE.test(k)) {
      const n = typeof v === "string" ? v.length : renderValue(v).length;
      parts.push(`${k}=<redacted:${n}>`);
    } else {
      parts.push(`${k}=${truncateStr(renderValue(v), DIAG_VALUE_MAX)}`);
    }
  }
  return `{${parts.join(", ")}}`;
}

export async function postPairing(
  publicKeyB64: string,
  fetcher: typeof fetch = fetch
): Promise<PairingOutcome> {
  let res: Response;
  try {
    res = await fetcher(PAIRING_URL, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ app_id: BEE_CLI_APP_ID, publicKey: publicKeyB64 }),
    });
  } catch {
    return { status: "error", message: "pairing service unreachable" };
  }
  let data: Record<string, unknown>;
  try {
    data = (await res.json()) as Record<string, unknown>;
  } catch {
    return { status: "error", message: `pairing service returned ${res.status}` };
  }
  if (!res.ok) return { status: "error", message: `pairing service returned ${res.status}` };
  const requestId = data["requestId"];
  const expiresAt = data["expiresAt"];
  const result = data["result"];
  const nestedEncryptedToken =
    result !== null && typeof result === "object" && !Array.isArray(result)
      ? (result as Record<string, unknown>)["encryptedToken"]
      : undefined;
  const encryptedToken =
    typeof data["encryptedToken"] === "string" ? data["encryptedToken"] : nestedEncryptedToken;
  switch (data["status"]) {
    case "pending":
      if (typeof requestId === "string" && typeof expiresAt === "string") {
        return { status: "pending", requestId, expiresAt };
      }
      break;
    case "completed":
      // Tolerate completed responses without requestId — the sealed pairing
      // state already carries the authoritative requestId, and the current
      // service may no longer echo it on completion. encryptedToken alone is
      // what the completed path actually needs. Also accept it nested under
      // result.encryptedToken — a shape the service has been observed to send.
      if (typeof encryptedToken === "string" && encryptedToken.length > 0) {
        return {
          status: "completed",
          requestId: typeof requestId === "string" ? requestId : "",
          encryptedToken,
        };
      }
      break;
    case "expired":
      return { status: "expired" };
  }
  const message = truncateStr(
    `unexpected pairing response shape (http ${res.status}): ${sanitizePairingBody(data)}`,
    DIAG_MESSAGE_MAX
  );
  console.log(message);
  return { status: "error", message };
}

/** The QR/deep-link target. Encodes ONLY the requestId — no secret in the image. */
export function buildConnectUrl(requestId: string): string {
  return `https://bee.computer/connect#${requestId}`;
}

// ---- envelope open: version(1) || nonce(24) || senderPk(32) || box ----
/** Returns the decrypted Bee token, or null on any format/auth failure.
 *  The returned string is a secret: never log it, never echo it. */
export function openPairingEnvelope(
  encryptedTokenB64: string,
  secretKey: Uint8Array
): string | null {
  let packed: Uint8Array;
  try {
    packed = b64ToBytes(encryptedTokenB64);
  } catch {
    return null;
  }
  if (packed.length < MIN_ENVELOPE_SIZE) return null;
  if (packed[0] !== ENCRYPTION_VERSION) return null;
  const nonce = packed.subarray(1, 1 + NONCE_SIZE);
  const senderPk = packed.subarray(1 + NONCE_SIZE, 1 + NONCE_SIZE + PUBLIC_KEY_SIZE);
  const box = packed.subarray(1 + NONCE_SIZE + PUBLIC_KEY_SIZE);
  const opened = nacl.box.open(box, nonce, senderPk, secretKey);
  if (!opened) return null;
  return new TextDecoder().decode(opened);
}

// ---- sealed pairing state: AES-GCM under HKDF(CONSENT_SIGNING_SECRET) ----
// The consent page carries this blob (ciphertext only) between /pairing/start
// and each /pairing/status poll, so the ephemeral secret key never exists at
// rest server-side and never exists in plaintext client-side.
export interface SealedPairingState {
  /** ephemeral x25519 public key, standard base64 (as sent on the wire) */
  pk: string;
  /** ephemeral x25519 secret key, standard base64 — plaintext only in-Worker */
  sk: string;
  requestId: string;
  /** gate-verified login this pairing belongs to; must match the signed consent state */
  login: string;
  /** OAuth client this pairing was started for; must match the signed consent
   *  state so a captured blob can't be replayed against a different client */
  clientId: string;
  /** issued-at, ms epoch */
  iat: number;
}

async function sealKey(secret: string): Promise<CryptoKey> {
  const ikm = await crypto.subtle.importKey("raw", te(secret), "HKDF", false, ["deriveKey"]);
  return crypto.subtle.deriveKey(
    { name: "HKDF", hash: "SHA-256", salt: te("bee-pairing-v1"), info: te("sealed-state") },
    ikm,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

export async function sealPairingState(
  state: SealedPairingState,
  secret: string
): Promise<string> {
  const key = await sealKey(secret);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(
    await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, te(JSON.stringify(state)))
  );
  const packed = new Uint8Array(iv.length + ct.length);
  packed.set(iv, 0);
  packed.set(ct, iv.length);
  return b64urlFromBytes(packed);
}

/** Returns null on any tamper/format/shape/age failure. */
export async function unsealPairingState(
  blob: string,
  secret: string,
  now: number = Date.now()
): Promise<SealedPairingState | null> {
  let packed: Uint8Array;
  try {
    packed = b64urlToBytes(blob);
  } catch {
    return null;
  }
  if (packed.length <= 12) return null;
  const iv = packed.subarray(0, 12);
  const ct = packed.subarray(12);
  let plain: Uint8Array;
  try {
    const key = await sealKey(secret);
    plain = new Uint8Array(await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ct));
  } catch {
    return null;
  }
  let state: SealedPairingState;
  try {
    state = JSON.parse(new TextDecoder().decode(plain)) as SealedPairingState;
  } catch {
    return null;
  }
  if (
    typeof state?.pk !== "string" ||
    typeof state?.sk !== "string" ||
    typeof state?.requestId !== "string" ||
    typeof state?.login !== "string" ||
    typeof state?.clientId !== "string" ||
    typeof state?.iat !== "number"
  ) {
    return null;
  }
  if (now - state.iat > SEALED_MAX_AGE_MS) return null;
  return state;
}

src/state.ts.content:
/** Round-trip the parsed OAuth request through GitHub's `state` parameter.
 *  Not secret (PKCE protects the grant); integrity is re-checked by the
 *  provider at completeAuthorization. Ported verbatim from git-repo-auth-mcp. */
export function encodeState(obj: unknown): string {
  const json = JSON.stringify(obj);
  const bytes = new TextEncoder().encode(json);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function decodeState<T>(s: string): T {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (s.length % 4)) % 4);
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return JSON.parse(new TextDecoder().decode(bytes)) as T;
}

// ---------------------------------------------------------------------------
// Signed consent state (v0.3 per-grant custody)
//
// The GitHub leg proves identity in /callback, then the GitHub user token is
// discarded. To capture the Bee token we render a consent form and POST it back
// to /consent — but by then we no longer have GitHub to re-derive the login.
// So we carry the gate-verified { oauthReqInfo, login } across that round-trip
// HMAC-signed, so the login the allow-list approved cannot be swapped by a
// tampered form field. The signing key is CONSENT_SIGNING_SECRET, a dedicated
// server-only secret (the dual-door change ended GITHUB_CLIENT_SECRET's dual
// use; see ticket bee-relay-cf-access). The payload is NOT
// confidential (no token rides in it) — it is integrity-protected, not hidden.
// ---------------------------------------------------------------------------

function b64urlEncodeBytes(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function b64urlDecodeToBytes(s: string): Uint8Array {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (s.length % 4)) % 4);
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"]
  );
}

/** Constant-time-ish comparison over equal-length byte arrays. */
function timingSafeEqual(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

/** Produce `<b64url(payload)>.<b64url(hmac)>` for the consent form hidden field. */
export async function signConsent(payload: unknown, secret: string): Promise<string> {
  const json = JSON.stringify(payload);
  const body = b64urlEncodeBytes(new TextEncoder().encode(json));
  const key = await hmacKey(secret);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(body)));
  return `${body}.${b64urlEncodeBytes(sig)}`;
}

/** Verify and decode a consent blob. Returns null on any tamper/format failure. */
export async function verifyConsent<T>(blob: string, secret: string): Promise<T | null> {
  const dot = blob.indexOf(".");
  if (dot <= 0) return null;
  const body = blob.slice(0, dot);
  const sigPart = blob.slice(dot + 1);
  if (!sigPart) return null;
  let presented: Uint8Array;
  try {
    presented = b64urlDecodeToBytes(sigPart);
  } catch {
    return null;
  }
  const key = await hmacKey(secret);
  const expected = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(body)));
  if (!timingSafeEqual(presented, expected)) return null;
  try {
    return JSON.parse(new TextDecoder().decode(b64urlDecodeToBytes(body))) as T;
  } catch {
    return null;
  }
}

src/telemetry.ts.content:
/**
 * Telemetry — minimal, optional, privacy-first observability for the read surface.
 *
 * Governance: docs/telemetry-governance.md (klappy://docs/products/bee-ai-auth-mcp/
 * telemetry-governance). Emission pattern: klappy://canon/decisions/
 * DR-20260514-0001-telemetry-wrapper-pattern (one wrapper per tool, in-memory,
 * per-call, swallow-on-failure, no domain opinion in the wrapper itself).
 *
 * WHAT THIS RECORDS: shape, never substance — tool name, a coarse Bee path CLASS
 * (never the raw path or a conversation id), cold/warm bridge state, a status
 * class, durations, and response byte size. It NEVER records the Bee token,
 * conversation content, raw paths/ids, search bodies, or any reversible identity.
 *
 * MULTI-TENANCY: each row is keyed by an OPAQUE per-grant tenant key — an HMAC of
 * the login under the existing GITHUB_CLIENT_SECRET (same secret-reuse precedent
 * as src/state.ts), never the login/Bee-id/email/token in the clear. Constant
 * under the single-tenant allow-list today; the partition key when the allow-list
 * widens (grant-level isolation, ledger E0014).
 *
 * SELF-HOST: the Analytics Engine binding is OPTIONAL. If BEE_TELEMETRY is unbound,
 * every emit is a silent no-op and the server behaves identically. No data ever
 * leaves the operator's own Cloudflare account.
 *
 * SLOT MAP IS STICKY — never reorder blobs/doubles; reuse-by-renumber is how the
 * upstream oddkit telemetry acquired bugs. Append only.
 */

import { COMMIT_SHA } from "./version";
import type { Env } from "./types";

/** Per-call record a tool handler populates with the domain-specific facts the
 *  generic wrapper cannot see (path class, bridge timing/cold, status). */
export interface ToolTelemetry {
  /** Coarse Bee path class for bee_read — NEVER the raw path or an id. */
  pathClass?: string;
  /** Wall-clock of the Bee call through the bridge (ms). */
  bridgeMs?: number;
  /** Whether the bound container served this request cold (from x-bridge-cold). */
  bridgeCold?: boolean;
  /** '2xx' | '4xx' | '5xx' | 'transport_fail' | 'n/a'. */
  statusClass?: string;
  /** Cache effectiveness — 0 until a cache tier exists. */
  cacheHits?: number;
  cacheLookups?: number;
}

/** Opaque, stable, non-reversible per-grant tenant key. Reuses GITHUB_CLIENT_SECRET
 *  as the HMAC key (already a server-only secret; see src/state.ts). Falls back to
 *  a constant on any crypto failure — telemetry must never break a request. */
export async function deriveTenantKey(env: Env, login: string): Promise<string> {
  try {
    const key = await crypto.subtle.importKey(
      "raw",
      new TextEncoder().encode(env.GITHUB_CLIENT_SECRET ?? ""),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"]
    );
    const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode("bee-tenant:" + login)));
    let bin = "";
    for (const b of sig) bin += String.fromCharCode(b);
    const b64 = btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
    return "t_" + b64.slice(0, 16);
  } catch {
    return "t_unknown";
  }
}

/** Map a Bee path to a coarse CLASS. Strips query + ids; never returns the raw path. */
export function classifyPath(path: string | undefined): string {
  const p = (path ?? "").split("?")[0];
  if (p === "/v1/me") return "me";
  if (p.startsWith("/v1/search")) return "search";
  if (p.startsWith("/v1/conversations")) return "conversations";
  if (p.startsWith("/v1/")) return "other";
  return "n/a";
}

/** Bucket an HTTP-ish status into a class. null/undefined => transport failure. */
export function statusClassOf(status: number | null | undefined): string {
  if (status == null) return "transport_fail";
  if (status >= 200 && status < 300) return "2xx";
  if (status >= 400 && status < 500) return "4xx";
  if (status >= 500) return "5xx";
  return "other";
}

function bytesOut(result: unknown): number {
  try {
    const content = (result as { content?: Array<{ text?: string }> } | undefined)?.content ?? [];
    let n = 0;
    for (const c of content) if (typeof c.text === "string") n += new TextEncoder().encode(c.text).length;
    return n;
  } catch {
    return 0;
  }
}

/**
 * Wrap a tool handler with one Analytics Engine emission per call. The wrapper
 * times total wall-clock and reads the envelope size; the handler contributes the
 * domain facts via the `tele` record it is handed. Emission is synchronous (no
 * racy clone()/waitUntil — the upstream emit-loss pitfall) and swallowed on any
 * failure so telemetry can never break a Bee request.
 */
export function withTelemetry<Args extends unknown[], R>(
  env: Env,
  tenantKey: string,
  tool: string,
  build: (tele: ToolTelemetry) => (...args: Args) => Promise<R>
): (...args: Args) => Promise<R> {
  return async (...args: Args): Promise<R> => {
    const tele: ToolTelemetry = {};
    const t0 = Date.now();
    const result = await build(tele)(...args);
    const durationMs = Date.now() - t0;
    try {
      const ds = env.BEE_TELEMETRY;
      if (ds) {
        const bridgeState = tele.bridgeCold === undefined ? "n/a" : tele.bridgeCold ? "cold" : "warm";
        const statusClass = tele.statusClass ?? ((result as { isError?: boolean })?.isError ? "5xx" : "2xx");
        // SLOT MAP (sticky — append only):
        // blobs:   1 event_type | 2 tenant | 3 tool | 4 path_class | 5 bridge_state | 6 status_class | 7 worker_version
        // doubles: 1 count | 2 duration_ms | 3 bridge_ms | 4 bytes_out | 5 cache_hits | 6 cache_lookups
        ds.writeDataPoint({
          indexes: [tenantKey],
          blobs: ["tool_call", tenantKey, tool, tele.pathClass ?? "n/a", bridgeState, statusClass, COMMIT_SHA],
          doubles: [1, durationMs, tele.bridgeMs ?? 0, bytesOut(result), tele.cacheHits ?? 0, tele.cacheLookups ?? 0],
        });
      }
    } catch {
      // swallow — telemetry must never break a request
    }
    return result;
  };
}

